	private static int Index => Array.IndexOf(Codes, L.Code);

	public static string? Lookup(string source)
	{
		int index = Index;
		if (index < 0)
		{
			return null;
		}
		if (Texts.TryGetValue(source, out string[] value))
		{
			return value[index];
		}
		string text = Texts.Keys.FirstOrDefault((string k) => string.Equals(k, source, StringComparison.OrdinalIgnoreCase));
		if (text == null)
		{
			return null;
		}
		string text2 = Texts[text][index];
		if (!source.Any(char.IsLetter) || !(source == source.ToUpperInvariant()))
		{
			return text2;
		}
		return text2.ToUpper(L.Culture);
	}

	public static string T(string source)
	{
		return Lookup(source) ?? EnglishText.Fix(source);
	}

	public static string F(string source, params object?[] args)
	{
		return string.Format(L.Culture, T(source), args);
	}

	public static string Note(int hidden)
	{
		int index = Index;
		string text = ((index < 0) ? "How it works: for each chest you opened since the weekly reset, a prize has a 1-in-N chance. Chests opened inside a Treasure Hour use the boosted rate. The big percentage and the solid bars are what you have really earned this week, so they stay empty until you open chests. The dashed outline (on the selected or hovered row) and the planner show what your chosen number of chests would be worth, with and without the Treasure Hour. Chests from a match still in progress count once it ends. Treasure Hour times come from your 2xflaw-odds.json file. Confirmed boosts are applied using your local schedule. Unconfirmed windows count as normal odds until their boosts are confirmed. Pirate Shop Access uses your all-time personal history (as configured); the other prizes are weekly. Chests without exact opening times use the base odds. Except for Gizmos, you cannot get the same prize twice." : Notes[index]);
		if (hidden <= 0)
		{
			return text;
		}
		string[] array = Hidden[index + 1];
		return text + string.Format(L.Culture, (hidden == 1) ? array[0] : array[1], hidden);
	}
